CREATE FUNCTION nmv_cli_executor_release_valid(e jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE AS $$
DECLARE p jsonb:=e->'plan'; r jsonb:=e->'receipt'; q jsonb:=p->'request'; x jsonb; i integer; t text;
BEGIN
  IF NOT nmv_cli_executor_shape_valid(e,$shape$__EVIDENCE_SHAPE__$shape$::jsonb) THEN RETURN false; END IF;
  IF e->'requestId' IS DISTINCT FROM q->'requestId' OR e->'owner' IS DISTINCT FROM q->'owner' OR e->'dispatchAt' IS DISTINCT FROM q->'dispatchAt'
    OR e->'bindingHash' IS DISTINCT FROM q->'bindingHash' OR e->'reference' IS DISTINCT FROM p->'reviewReference'
    OR e->'notBefore' IS DISTINCT FROM r->'observedAt' OR r->>'planHash' IS DISTINCT FROM encode(sha256(convert_to(nmv_boundary_canonical(p),'UTF8')),'hex')
    OR p->'executor' IS DISTINCT FROM r->'executor' OR p->'topology' IS DISTINCT FROM r->'topology'
    OR p->'executor'->>'baseUrlHash' IS DISTINCT FROM encode(sha256(convert_to(p->'executor'->>'baseUrl','UTF8')),'hex')
    OR q->'provider' IS DISTINCT FROM q->'transport'->'provider' OR q->'model' IS DISTINCT FROM q->'transport'->'model'
    OR q->'chargedTokens' IS DISTINCT FROM q->'totalTokenBound' THEN RETURN false; END IF;
  FOREACH t IN ARRAY ARRAY[e->>'dispatchAt',e->>'notBefore',e->>'evaluatedAt',p->>'createdAt',r->>'observedAt',p->'interval'->>'beforeNativeAt'] LOOP
    IF to_char(t::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')<>t THEN RETURN false; END IF;
  END LOOP;
  t:=p->'control'->>'updatedAt';
  IF to_char(t::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')<>t THEN RETURN false; END IF;
  IF (p->'interval'->>'beforeNativeAt')::timestamptz >= (q->>'dispatchAt')::timestamptz
    OR (p->>'createdAt')::timestamptz < (q->>'dispatchAt')::timestamptz OR t::timestamptz > (p->>'createdAt')::timestamptz
    OR (e->>'evaluatedAt')::timestamptz < (r->>'observedAt')::timestamptz OR (r->>'observedAt')::timestamptz < (p->>'createdAt')::timestamptz
    OR (e->>'evaluatedAt')::timestamptz-(p->>'createdAt')::timestamptz>interval '30 minutes'
    OR (e->>'evaluatedAt')::timestamptz-(r->>'observedAt')::timestamptz>interval '5 minutes'
    OR jsonb_array_length(r->'exits')<>jsonb_array_length(p->'candidates') THEN RETURN false; END IF;
  IF (SELECT count(DISTINCT a->>'taskId') FROM jsonb_array_elements(p->'candidates') a)<>jsonb_array_length(p->'candidates')
    OR (SELECT count(DISTINCT a->>'containerId') FROM jsonb_array_elements(p->'candidates') a)<>jsonb_array_length(p->'candidates')
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'candidates') a WHERE a->>'taskId'=p->'interval'->>'singleTaskId') THEN RETURN false; END IF;
  FOR i IN 0..jsonb_array_length(p->'candidates')-1 LOOP
    x:=p->'candidates'->i;
    IF x->'serviceId' IS DISTINCT FROM p->'executor'->'serviceId' OR x->'nodeId' IS DISTINCT FROM p->'executor'->'nodeId'
      OR r->'exits'->i->'identity' IS DISTINCT FROM x
      OR r->'exits'->i->'initClosure'->>'kind'='removed_after_trusted_init_exit' AND r->'exits'->i->>'containerState'<>'removed' THEN RETURN false; END IF;
  END LOOP;
  IF r->'wholeService'->'endpointClosed'->>'kind'='trusted_forwarder_no_backend'
    AND r->'wholeService'->'endpointClosed'->'backendServiceId' IS DISTINCT FROM p->'executor'->'serviceId' THEN RETURN false; END IF;
  RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
