-- Snapshot the COMPLETE existing binding checks; reconstruct only the original dispatched state for this extra terminal branch.
DO $$
DECLARE predicates text;
BEGIN
  SELECT string_agg('('||substring(pg_get_constraintdef(oid) FROM 7)||')',' AND ' ORDER BY conname) INTO predicates FROM pg_constraint
    WHERE conrelid='model_capacity_requests'::regclass AND conname IN ('model_capacity_requests_logical_check','model_capacity_requests_members_check','model_capacity_requests_dispatch_check');
  IF predicates IS NULL OR (SELECT count(*) FROM pg_constraint WHERE conrelid='model_capacity_requests'::regclass AND conname IN ('model_capacity_requests_logical_check','model_capacity_requests_members_check','model_capacity_requests_dispatch_check'))<>3 THEN RAISE EXCEPTION 'cli_executor_predecessor_missing'; END IF;
  EXECUTE 'CREATE FUNCTION nmv_cli_executor_predecessor_valid(v jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $fn$ SELECT coalesce(('||predicates||'),false) FROM jsonb_populate_record(NULL::model_capacity_requests,v||''{"state":"dispatched","terminal_evidence":null,"terminal_evidence_hash":null,"settled_at":null}''::jsonb) model_capacity_requests $fn$';
END $$;
--> statement-breakpoint
CREATE FUNCTION nmv_cli_executor_request_valid(v jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE AS $$
DECLARE e jsonb:=v->'terminal_evidence'; q jsonb:=e->'plan'->'request'; b jsonb:=v->'dispatch_binding';
BEGIN
  RETURN coalesce(v->>'state'='withdrawn' AND v->'settled_at'='null'::jsonb AND v->'token'<>'null'::jsonb
    AND nmv_cli_executor_release_valid(e) AND nmv_cli_executor_predecessor_valid(v)
    AND v->>'terminal_evidence_hash'=encode(sha256(convert_to(nmv_boundary_canonical(e),'UTF8')),'hex')
    AND e->>'requestId'=v->>'request_id' AND e->'owner'->>'instanceId'=v->>'owner_instance_id' AND e->'owner'->>'bootId'=v->>'owner_boot_id'
    AND e->>'bindingHash'=v->>'dispatch_binding_hash' AND (e->>'dispatchAt')::timestamptz=(v->>'dispatched_at')::timestamptz
    AND q->>'tokenHash'=encode(sha256(convert_to(v->>'token','UTF8')),'hex') AND q->'epoch'=v->'epoch' AND q->'revision'=v->'revision'
    AND q->>'policyHash'=v->>'policy_hash' AND q->>'providerBudgetId'=v->>'provider_budget_id' AND q->>'groupId'=v->>'group_id'
    AND q->>'routeId'=v->>'route_id' AND q->>'provider'=v->>'provider' AND q->>'model'=v->>'model' AND q->>'logicalWorkKey'=v->>'logical_work_key'
    AND b->>'kind'='publication_classify_cli' AND v->>'dispatch_binding_hash'=encode(sha256(convert_to(nmv_boundary_canonical(b),'UTF8')),'hex')
    AND q->'inputHash'=b->'inputHash' AND q->'payloadHash'=b->'payloadHash'
    AND q->'transport'=b->'transport' AND q->'totalTokenBound'=b->'totalTokenBound' AND q->'chargedTokens'=b->'chargedTokens',false);
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
--> statement-breakpoint
DO $$
DECLARE n text; old_predicate text;
BEGIN
  FOREACH n IN ARRAY ARRAY['model_capacity_requests_logical_check','model_capacity_requests_members_check','model_capacity_requests_dispatch_check','model_capacity_requests_terminal_check'] LOOP
    SELECT substring(pg_get_constraintdef(oid) FROM 7) INTO STRICT old_predicate FROM pg_constraint WHERE conrelid='model_capacity_requests'::regclass AND conname=n;
    EXECUTE format('ALTER TABLE model_capacity_requests DROP CONSTRAINT %I',n);
    EXECUTE format('ALTER TABLE model_capacity_requests ADD CONSTRAINT %I CHECK ((%s) OR nmv_cli_executor_request_valid(to_jsonb(model_capacity_requests)))',n,old_predicate);
  END LOOP;
  SELECT substring(pg_get_constraintdef(oid) FROM 7) INTO STRICT old_predicate FROM pg_constraint WHERE conrelid='model_capacity_events'::regclass AND conname='model_capacity_events_kind_check';
  ALTER TABLE model_capacity_events DROP CONSTRAINT model_capacity_events_kind_check;
  EXECUTE 'ALTER TABLE model_capacity_events ADD CONSTRAINT model_capacity_events_kind_check CHECK (('||old_predicate||') OR coalesce(kind=''dispatch_released'' AND from_state=''dispatched'' AND to_state=''withdrawn'' AND reason IS NULL AND nmv_cli_executor_release_valid(evidence) AND evidence->>''requestId''=request_id::text AND evidence->''plan''->''request''->''epoch''=to_jsonb(epoch) AND evidence->''plan''->''request''->''revision''=to_jsonb(revision) AND evidence->''plan''->''request''->>''policyHash''=policy_hash,false))';
END $$;
